import re
from typing import List, Dict, Tuple, Any, Optional

# ----------------------------------------------------------------------
# Utilities -------------------------------------------------------------
# ----------------------------------------------------------------------
def _is_numeric(s: str) -> bool:
    """Return True if s contains a numeric value that can be parsed."""
    if s is None:
        return False
    s = s.strip()
    if not s:
        return False
    # strip common prefixes/suffixes
    s = s.replace('$', '').replace('€', '').replace('–', '-').replace('\u2014', '-')
    # remove commas and parentheses for negatives
    s = s.replace(',', '').replace('(', '-').replace(')', '')
    try:
        float(s)
        return True
    except ValueError:
        return False

def _to_number(s: str) -> Any:
    """Convert a numeric string to int or float."""
    if s is None:
        return None
    s = s.strip()
    if not s:
        return None
    s = s.replace('$', '').replace('€', '').replace('–', '-').replace('\u2014', '-')
    s = s.replace(',', '').replace('(', '-').replace(')', '')
    try:
        if '.' in s:
            return float(s)
        else:
            return int(s)
    except ValueError:
        return None

def _extract_years_from_headers(headers: List[str]) -> List[int]:
    """Return list of years that appear in header strings."""
    years = []
    yr_re = re.compile(r'\b(20\d{2})\b')
    for header in headers:
        m = yr_re.search(header)
        if m:
            years.append(int(m.group(1)))
    return years

def _cell_has_time(row: List[str], time_col_idx: int) -> bool:
    if time_col_idx is None:
        return False
    return _is_numeric(row[time_col_idx])

