def entities(doc: dict, scope: str) -> List[Dict[str, str]]:
    """
    Return a list of entities occurring in the tables of the given scope.
    Each entity is represented by a 3-element dict: id, description.
    The id is constructed from the node id and the row index.
    """
    ents = []
    seen = set()
    for node in scope_nodes(doc, node_by_title(doc, scope)):
        if node.get('kind') != 'table':
            continue
        node_id = node['node_id']
        for row_index, row in table_rows(node):
            if not row:
                continue
            desc = row.get('col0', '').strip()
            if not desc:
                continue
            ent_id = f"ent:{node_id}:{row_index}"
            if ent_id in seen:
                continue
            seen.add(ent_id)
            ents.append({"id": ent_id, "description": desc})
    return ents

def recorded_end(doc: dict, scope: str) -> Optional[float]:
    """
    Return the greatest time value found in a table column whose header
    contains a 4-digit year.  Return None if no such time is found.
    """
    max_year = None
    for node in scope_nodes(doc, node_by_title(doc, scope)):
        if node.get('kind') != 'table':
            continue
        headers = node['table']['columns']
        year_cols = _extract_years_from_headers(headers)
        if not year_cols:
            continue
        # assume each year column represents a time point
        for col_index in year_cols:
            header = headers[col_index] if col_index < len(headers) else ""
            # extract year number from header
            yr = _extract_years_from_headers([header])
            if not yr:
                continue
            year_val = yr[0]
            if max_year is None or year_val > max_year:
                max_year = year_val
    return max_year

def inputs(doc: dict, scope: str) -> List[Dict[str, Any]]:
    """
    For this simplified model, we treat no external inputs.
    """
    return []

def outcomes(doc: dict, scope: str) -> List[Dict[str, Any]]:
    """
    For each numeric cell in the tables of the scope, create an outcome record.
    Each outcome references the entity represented by the row's first column.
    """
    out = []
    for node in scope_nodes(doc, node_by_title(doc, scope)):
        if node.get('kind') != 'table':
            continue
        node_id = node['node_id']
        headers = node['table']['columns']
        # identify a time column if any
        time_col_idx = None
        year_cols = _extract_years_from_headers(headers)
        if year_cols:
            # pick first year column as time column
            # Find the header index that matches the year
            for idx, h in enumerate(headers):
                if any(str(y) == h.strip() for y in year_cols):
                    time_col_idx = idx
                    break
        for row_index, row in table_rows(node):
            # get entity description
            desc = row.get('col0', '').strip()
            if not desc:
                continue
            entity_id = f"ent:{node_id}:{row_index}"
            # gather times for this row: use time column if numeric
            time_val = None
            if time_col_idx is not None and _is_numeric(row.get(headers[time_col_idx], '')):
                time_val = _to_number(row[headers[time_col_idx]])
            # iterate columns
            for col_name, cell in row.items():
                if col_name == 'col0':
                    continue
                if not _is_numeric(cell):
                    continue
                val = _to_number(cell)
                out.append({
                    "time": time_val,
                    "kind": "quantity",
                    "entities": [entity_id],
                    "value": val,
                    "src": [[node_id, row_index, [col_name, (headers[time_col_idx] if time_col_idx is not None else None)]]]
                })
    return out

